// =====================================================================
// 🏢 AGENCY ROUTING & PROFILE (Non-Sensitive Agency Identifiers)
// Credentials (Postgres, OpenAI, WhatsApp) live in n8n Credential Manager
// =====================================================================

const agencyInfo = {
  // Agency UUID from Supabase public.agencies table
  agencyId: "00000000-0000-0000-0000-000000000001",

  // Agency Profile for customer greetings
  agencyName: "Al-Raziq Estate & Builders",
  agentPhone: "+92 300 8251940",
  primaryCity: "Karachi & Lahore",

  // Meta Phone Number ID (from WhatsApp Business App Dashboard)
  phoneNumberId: "104928392019482"
};

const webhookData = $input.first()?.json || {};

return [{
  json: {
    ...webhookData,
    ...agencyInfo
  }
}];

// Extract incoming message details from Meta WhatsApp Cloud API payload
const item = $input.first().json;
const body = item.body || item;

let senderPhone = '';
let customerName = 'Customer';
let messageText = '';
let messageId = '';
let messageTimestamp = new Date().toISOString();
let isMessage = false;

// WhatsApp Cloud API payload validation
if (body && body.entry && body.entry[0] && body.entry[0].changes && body.entry[0].changes[0]) {
  const value = body.entry[0].changes[0].value;

  // Check if it's an incoming customer message (ignore delivery receipts)
  if (value.messages && value.messages[0]) {
    isMessage = true;
    const msg = value.messages[0];
    messageId = msg.id || '';

    // Normalize phone number to +92 Pakistani standard format
    let rawPhone = msg.from || '';
    if (rawPhone.startsWith('92')) {
      senderPhone = '+' + rawPhone;
    } else if (rawPhone.startsWith('03')) {
      senderPhone = '+92' + rawPhone.substring(1);
    } else if (rawPhone.startsWith('+')) {
      senderPhone = rawPhone;
    } else {
      senderPhone = '+92' + rawPhone;
    }

    // Customer name from WhatsApp profile
    if (value.contacts && value.contacts[0] && value.contacts[0].profile) {
      customerName = value.contacts[0].profile.name || 'Customer';
    }

    // Message text body
    if (msg.type === 'text' && msg.text) {
      messageText = msg.text.body || '';
    } else if (msg.type === 'interactive' && msg.interactive) {
      messageText = msg.interactive.button_reply?.title || msg.interactive.list_reply?.title || '';
    } else {
      messageText = `[Customer sent ${msg.type || 'media'}]`;
    }

    if (msg.timestamp) {
      messageTimestamp = new Date(parseInt(msg.timestamp) * 1000).toISOString();
    }
  }
}

return [{
  json: {
    isMessage,
    senderPhone,
    customerName,
    messageText,
    messageId,
    messageTimestamp,
    agencyId: item.agencyId,
    agencyName: item.agencyName,
    agentPhone: item.agentPhone,
    primaryCity: item.primaryCity,
    phoneNumberId: item.phoneNumberId
  }
}];

const prev = $('Parse WhatsApp Payload').first().json;
const existingLeads = $input.all().map(i => i.json);

let lead = null;
let isNewLead = false;

if (existingLeads.length > 0 && existingLeads[0].id) {
  lead = existingLeads[0];
} else {
  isNewLead = true;
}

return [{
  json: {
    ...prev,
    lead,
    isNewLead
  }
}];

const parseData = $('Parse WhatsApp Payload').first().json;
let lead = null;

// If newly created
const created = $input.first()?.json;
if (created && (created.id || (Array.isArray(created) && created[0]?.id))) {
  lead = Array.isArray(created) ? created[0] : created;
} else {
  lead = $('Process Lead Status').first().json.lead;
}

// Detect human takeover triggers in English, Roman Urdu & Urdu script
const text = (parseData.messageText || '').toLowerCase();
const humanKeywords = [
  'human',
  'agent',
  'call me',
  'call karein',
  'call karo',
  'phone',
  'number dein',
  'baat karni',
  'rabta',
  'live person',
  'insan',
  'banda',
  'owner se',
  'کال',
  'ایجنٹ',
  'بات کرنی'
];

const requestedHuman = humanKeywords.some(kw => text.includes(kw));

let botState = 'active';
if (lead.bot_paused) {
  botState = 'paused_already';
} else if (requestedHuman) {
  botState = 'requesting_human';
}

return [{
  json: {
    ...parseData,
    lead,
    leadId: lead.id,
    botState,
    requestedHuman
  }
}];

